charset_normalizer.cd.encoding_languages:
@lru_cache()
def encoding_languages(iana_name: str) -> list[str]:
    """
    Single-byte encoding language association. Some code page are heavily linked to particular language(s).
    This function does the correspondence.
    """
    try:
        unicode_ranges: list[str] = encoding_unicode_range(iana_name)
    except ImportError:
        return []
    primary_range: str | None = None
    for specified_range in unicode_ranges:
        if 'Latin' not in specified_range:
            primary_range = specified_range
            break
    if primary_range is None:
        return ['Latin Based']
    return unicode_range_languages(primary_range)

charset_normalizer.api.from_bytes:
def from_bytes(sequences: bytes | bytearray, steps: int = 5, chunk_size: int = 512, threshold: float = 0.2, cp_isolation: list[str] | None = None, cp_exclusion: list[str] | None = None, preemptive_behaviour: bool = True, explain: bool = False, language_threshold: float = 0.1, enable_fallback: bool = True) -> CharsetMatches:
    """
    Given a raw bytes sequence, return the best possibles charset usable to render str objects.
    If there is no results, it is a strong indicator that the source is binary/not text.
    By default, the process will extract 5 blocks of 512o each to assess the mess and coherence of a given sequence.
    And will give up a particular code page after 20% of measured mess. Those criteria are customizable at will.

    The preemptive behavior DOES NOT replace the traditional detection workflow, it prioritize a particular code page
    but never take it for granted. Can improve the performance.

    You may want to focus your attention to some code page or/and not others, use cp_isolation and cp_exclusion for that
    purpose.

    This function will strip the SIG in the payload/sequence every time except on UTF-16, UTF-32.
    By default the library does not setup any handler other than the NullHandler, if you choose to set the 'explain'
    toggle to True it will alter the logger configuration to add a StreamHandler that is suitable for debugging.
    Custom logging format and handler can be set manually.
    """
    if not isinstance(sequences, (bytearray, bytes)):
        raise TypeError('Expected object of type bytes or bytearray, got: {}'.format(type(sequences)))
    if explain:
        previous_logger_level: int = logger.level
        logger.addHandler(explain_handler)
        logger.setLevel(TRACE)
    length: int = len(sequences)
    if length == 0:
        logger.debug('Encoding detection on empty bytes, assuming utf_8 intention.')
        if explain:
            logger.removeHandler(explain_handler)
            logger.setLevel(previous_logger_level)
        return CharsetMatches([CharsetMatch(sequences, 'utf_8', 0.0, False, [], '')])
    if cp_isolation is not None:
        logger.log(TRACE, 'cp_isolation is set. use this flag for debugging purpose. limited list of encoding allowed : %s.', ', '.join(cp_isolation))
        cp_isolation = [iana_name(cp, False) for cp in cp_isolation]
    else:
        cp_isolation = []
    if cp_exclusion is not None:
        logger.log(TRACE, 'cp_exclusion is set. use this flag for debugging purpose. limited list of encoding excluded : %s.', ', '.join(cp_exclusion))
        cp_exclusion = [iana_name(cp, False) for cp in cp_exclusion]
    else:
        cp_exclusion = []
    if length <= chunk_size * steps:
        logger.log(TRACE, 'override steps (%i) and chunk_size (%i) as content does not fit (%i byte(s) given) parameters.', steps, chunk_size, length)
        steps = 1
        chunk_size = length
    if (steps > 1 and length / steps < chunk_size):
        chunk_size = int(length / steps)
    is_too_small_sequence: bool = len(sequences) < TOO_SMALL_SEQUENCE
    is_too_large_sequence: bool = len(sequences) >= TOO_BIG_SEQUENCE
    if is_too_small_sequence:
        logger.log(TRACE, 'Trying to detect encoding from a tiny portion of ({}) byte(s).'.format(length))
    elif is_too_large_sequence:
        logger.log(TRACE, 'Using lazy str decoding because the payload is quite large, ({}) byte(s).'.format(length))
    prioritized_encodings: list[str] = []
    specified_encoding: str | None = (any_specified_encoding(sequences) if preemptive_behaviour else None)
    if specified_encoding is not None:
        prioritized_encodings.append(specified_encoding)
        logger.log(TRACE, 'Detected declarative mark in sequence. Priority +1 given for %s.', specified_encoding)
    tested: set[str] = set()
    tested_but_hard_failure: list[str] = []
    tested_but_soft_failure: list[str] = []
    soft_failure_skip: set[str] = set()
    success_fast_tracked: set[str] = set()
    payload_result_cache: dict[(int, tuple[(float, list[tuple[(str, float)]], bool)])] = {}
    cached_mess_ratio = lru_cache(maxsize=None)(mess_ratio)
    cached_coherence_ratio = lru_cache(maxsize=None)(coherence_ratio)
    definitive_match_found: bool = False
    definitive_target_languages: set[str] = set()
    post_definitive_sb_success_count: int = 0
    POST_DEFINITIVE_SB_CAP: int = 7
    mb_definitive_match_found: bool = False
    fallback_ascii: CharsetMatch | None = None
    fallback_u8: CharsetMatch | None = None
    fallback_specified: CharsetMatch | None = None
    results: CharsetMatches = CharsetMatches()
    early_stop_results: CharsetMatches = CharsetMatches()
    (sig_encoding, sig_payload) = identify_sig_or_bom(sequences)
    if sig_encoding is not None:
        prioritized_encodings.append(sig_encoding)
        logger.log(TRACE, 'Detected a SIG or BOM mark on first %i byte(s). Priority +1 given for %s.', len(sig_payload), sig_encoding)
    prioritized_encodings.append('ascii')
    if 'utf_8' not in prioritized_encodings:
        prioritized_encodings.append('utf_8')
    for encoding_iana in prioritized_encodings + IANA_SUPPORTED_MB_FIRST:
        if (cp_isolation and encoding_iana not in cp_isolation):
            continue
        if (cp_exclusion and encoding_iana in cp_exclusion):
            continue
        if encoding_iana in tested:
            continue
        tested.add(encoding_iana)
        decoded_payload: str | None = None
        bom_or_sig_available: bool = sig_encoding == encoding_iana
        strip_sig_or_bom: bool = (bom_or_sig_available and should_strip_sig_or_bom(encoding_iana))
        if (encoding_iana in {'utf_16', 'utf_32'} and not bom_or_sig_available):
            logger.log(TRACE, "Encoding %s won't be tested as-is because it require a BOM. Will try some sub-encoder LE/BE.", encoding_iana)
            continue
        if (encoding_iana in {'utf_7'} and not bom_or_sig_available):
            logger.log(TRACE, "Encoding %s won't be tested as-is because detection is unreliable without BOM/SIG.", encoding_iana)
            continue
        if encoding_iana in soft_failure_skip:
            logger.log(TRACE, '%s is deemed too similar to a code page that was already considered unsuited. Continuing!', encoding_iana)
            continue
        if encoding_iana in success_fast_tracked:
            logger.log(TRACE, 'Skipping %s: already fast-tracked from a similar successful encoding.', encoding_iana)
            continue
        try:
            is_multi_byte_decoder: bool = is_multi_byte_encoding(encoding_iana)
        except (ModuleNotFoundError, ImportError):
            logger.log(TRACE, 'Encoding %s does not provide an IncrementalDecoder', encoding_iana)
            continue
        if definitive_match_found:
            if not is_multi_byte_decoder:
                enc_languages = set(encoding_languages(encoding_iana))
            else:
                enc_languages = set(mb_encoding_languages(encoding_iana))
            if not enc_languages.intersection(definitive_target_languages):
                logger.log(TRACE, 'Skipping %s: definitive match already found, this encoding targets different languages (%s vs %s).', encoding_iana, enc_languages, definitive_target_languages)
                continue
        if (definitive_match_found and not is_multi_byte_decoder and post_definitive_sb_success_count >= POST_DEFINITIVE_SB_CAP):
            logger.log(TRACE, 'Skipping %s: already accumulated %d same-family results after definitive match (cap=%d).', encoding_iana, post_definitive_sb_success_count, POST_DEFINITIVE_SB_CAP)
            continue
        if (mb_definitive_match_found and not is_multi_byte_decoder):
            logger.log(TRACE, 'Skipping single-byte %s: multi-byte definitive match already found.', encoding_iana)
            continue
        deferred_decoding: bool = (not is_multi_byte_decoder and not is_too_large_sequence)
        try:
            if (is_too_large_sequence and not is_multi_byte_decoder):
                str((sequences[:int(500000.0)] if not strip_sig_or_bom else sequences[len(sig_payload):int(500000.0)]), encoding=encoding_iana)
            elif not deferred_decoding:
                if (encoding_iana == 'utf_7' and bom_or_sig_available):
                    decoded_payload = str(sequences, encoding=encoding_iana)
                    if (decoded_payload and decoded_payload[0] == '\ufeff'):
                        decoded_payload = decoded_payload[1:]
                else:
                    decoded_payload = str((sequences if not strip_sig_or_bom else sequences[len(sig_payload):]), encoding=encoding_iana)
        except (UnicodeDecodeError, LookupError) as e:
            if not isinstance(e, LookupError):
                logger.log(TRACE, 'Code page %s does not fit given bytes sequence at ALL. %s', encoding_iana, str(e))
            tested_but_hard_failure.append(encoding_iana)
            continue
        r_ = range((0 if not bom_or_sig_available else len(sig_payload)), length, int(length / steps))
        multi_byte_bonus: bool = (is_multi_byte_decoder and decoded_payload is not None and len(decoded_payload) < length)
        if multi_byte_bonus:
            logger.log(TRACE, 'Code page %s is a multi byte encoding table and it appear that at least one character was encoded using n-bytes.', encoding_iana)
        max_chunk_gave_up: int = int(len(r_) / 4)
        max_chunk_gave_up = max(max_chunk_gave_up, 2)
        early_stop_count: int = 0
        lazy_str_hard_failure = False
        md_chunks: list[str] = []
        md_ratios = []
        try:
            for chunk in cut_sequence_chunks(sequences, encoding_iana, r_, chunk_size, bom_or_sig_available, strip_sig_or_bom, sig_payload, is_multi_byte_decoder, decoded_payload, deferred_decoding):
                md_chunks.append(chunk)
                md_ratios.append(cached_mess_ratio(chunk, threshold, (explain and 1 <= len(cp_isolation) <= 2)))
                if md_ratios[-1] >= threshold:
                    early_stop_count += 1
                if (early_stop_count >= max_chunk_gave_up or (bom_or_sig_available and not strip_sig_or_bom)):
                    break
        except (UnicodeDecodeError, LookupError) as e:
            if deferred_decoding:
                logger.log(TRACE, 'Code page %s does not fit given bytes sequence at ALL. %s', encoding_iana, str(e))
                tested_but_hard_failure.append(encoding_iana)
                continue
            logger.log(TRACE, 'LazyStr Loading: After MD chunk decode, code page %s does not fit given bytes sequence at ALL. %s', encoding_iana, str(e))
            early_stop_count = max_chunk_gave_up
            lazy_str_hard_failure = True
        if (not lazy_str_hard_failure and is_too_large_sequence and not is_multi_byte_decoder):
            try:
                sequences[int(50000.0):].decode(encoding_iana, errors='strict')
            except UnicodeDecodeError as e:
                logger.log(TRACE, 'LazyStr Loading: After final lookup, code page %s does not fit given bytes sequence at ALL. %s', encoding_iana, str(e))
                tested_but_hard_failure.append(encoding_iana)
                continue
        mean_mess_ratio: float = (sum(md_ratios) / len(md_ratios) if md_ratios else 0.0)
        if (mean_mess_ratio >= threshold or early_stop_count >= max_chunk_gave_up):
            tested_but_soft_failure.append(encoding_iana)
            if encoding_iana in IANA_SUPPORTED_SIMILAR:
                soft_failure_skip.update(IANA_SUPPORTED_SIMILAR[encoding_iana])
            if (decoded_payload is not None and not is_multi_byte_decoder):
                payload_result_cache.setdefault(hash(decoded_payload), (mean_mess_ratio, [], False))
            logger.log(TRACE, '%s was excluded because of initial chaos probing. Gave up %i time(s). Computed mean chaos is %f %%.', encoding_iana, early_stop_count, round(mean_mess_ratio * 100, ndigits=3))
            if (enable_fallback and encoding_iana in ['ascii', 'utf_8', specified_encoding, 'utf_16', 'utf_32'] and not lazy_str_hard_failure):
                if decoded_payload is None:
                    try:
                        decoded_payload = str((sequences if not strip_sig_or_bom else sequences[len(sig_payload):]), encoding=encoding_iana)
                    except (UnicodeDecodeError, LookupError):
                        logger.log(TRACE, '%s does not decode the whole payload: fallback entry withheld.', encoding_iana)
                        continue
                    if is_too_large_sequence:
                        decoded_payload = None
                fallback_entry = CharsetMatch(sequences, encoding_iana, threshold, bom_or_sig_available, [], decoded_payload, preemptive_declaration=specified_encoding)
                if encoding_iana == specified_encoding:
                    fallback_specified = fallback_entry
                elif encoding_iana == 'ascii':
                    fallback_ascii = fallback_entry
                else:
                    fallback_u8 = fallback_entry
            continue
        if deferred_decoding:
            try:
                decoded_payload = str((sequences if not strip_sig_or_bom else sequences[len(sig_payload):]), encoding=encoding_iana)
            except (UnicodeDecodeError, LookupError) as e:
                logger.log(TRACE, 'Code page %s does not fit given bytes sequence at ALL. %s', encoding_iana, str(e))
                tested_but_hard_failure.append(encoding_iana)
                continue
        if (decoded_payload is not None and not is_multi_byte_decoder):
            payload_hash: int = hash(decoded_payload)
            cached = payload_result_cache.get(payload_hash)
            if cached is not None:
                (cached_mess, cached_cd, cached_passed) = cached
                if cached_passed:
                    fast_match = CharsetMatch(sequences, encoding_iana, cached_mess, bom_or_sig_available, cached_cd, (decoded_payload if (not is_too_large_sequence or encoding_iana in [specified_encoding, 'ascii', 'utf_8']) else None), preemptive_declaration=specified_encoding)
                    results.append(fast_match)
                    success_fast_tracked.add(encoding_iana)
                    logger.log(TRACE, '%s fast-tracked (identical decoded payload to a prior encoding, chaos=%f %%).', encoding_iana, round(cached_mess * 100, ndigits=3))
                    if (encoding_iana in [specified_encoding, 'ascii', 'utf_8'] and cached_mess < 0.1):
                        if cached_mess == 0.0:
                            logger.debug('Encoding detection: %s is most likely the one.', fast_match.encoding)
                            if explain:
                                logger.removeHandler(explain_handler)
                                logger.setLevel(previous_logger_level)
                            return CharsetMatches([fast_match])
                        early_stop_results.append(fast_match)
                    if (len(early_stop_results) and ((specified_encoding is None or specified_encoding in tested)) and 'ascii' in tested and 'utf_8' in tested):
                        probable_result: CharsetMatch = early_stop_results.best()
                        logger.debug('Encoding detection: %s is most likely the one.', probable_result.encoding)
                        if explain:
                            logger.removeHandler(explain_handler)
                            logger.setLevel(previous_logger_level)
                        return CharsetMatches([probable_result])
                    continue
                else:
                    tested_but_soft_failure.append(encoding_iana)
                    logger.log(TRACE, '%s fast-skipped (identical decoded payload to a prior encoding that failed chaos probing).', encoding_iana)
                    if (enable_fallback and encoding_iana in ['ascii', 'utf_8', specified_encoding, 'utf_16', 'utf_32']):
                        fallback_entry = CharsetMatch(sequences, encoding_iana, threshold, bom_or_sig_available, [], decoded_payload, preemptive_declaration=specified_encoding)
                        if encoding_iana == specified_encoding:
                            fallback_specified = fallback_entry
                        elif encoding_iana == 'ascii':
                            fallback_ascii = fallback_entry
                        else:
                            fallback_u8 = fallback_entry
                    continue
        logger.log(TRACE, '%s passed initial chaos probing. Mean measured chaos is %f %%', encoding_iana, round(mean_mess_ratio * 100, ndigits=3))
        if not is_multi_byte_decoder:
            target_languages: list[str] = encoding_languages(encoding_iana)
        else:
            target_languages = mb_encoding_languages(encoding_iana)
        if target_languages:
            logger.log(TRACE, '{} should target any language(s) of {}'.format(encoding_iana, str(target_languages)))
        cd_ratios = []
        if encoding_iana != 'ascii':
            lg_inclusion: str | None = (','.join(target_languages) if target_languages else None)
            for chunk in md_chunks:
                chunk_languages = cached_coherence_ratio(chunk, language_threshold, lg_inclusion)
                cd_ratios.append(chunk_languages)
        cd_ratios_merged = merge_coherence_ratios(cd_ratios)
        if cd_ratios_merged:
            logger.log(TRACE, 'We detected language {} using {}'.format(cd_ratios_merged, encoding_iana))
        current_match = CharsetMatch(sequences, encoding_iana, mean_mess_ratio, bom_or_sig_available, cd_ratios_merged, (decoded_payload if (not is_too_large_sequence or encoding_iana in [specified_encoding, 'ascii', 'utf_8']) else None), preemptive_declaration=specified_encoding)
        results.append(current_match)
        if (decoded_payload is not None and not is_multi_byte_decoder):
            payload_result_cache.setdefault(hash(decoded_payload), (mean_mess_ratio, cd_ratios_merged, True))
        if (definitive_match_found and not is_multi_byte_decoder and mean_mess_ratio < 0.02):
            post_definitive_sb_success_count += 1
        if (encoding_iana in [specified_encoding, 'ascii', 'utf_8'] and mean_mess_ratio < 0.1):
            if mean_mess_ratio == 0.0:
                logger.debug('Encoding detection: %s is most likely the one.', current_match.encoding)
                if explain:
                    logger.removeHandler(explain_handler)
                    logger.setLevel(previous_logger_level)
                return CharsetMatches([current_match])
            early_stop_results.append(current_match)
        if (len(early_stop_results) and ((specified_encoding is None or specified_encoding in tested)) and 'ascii' in tested and 'utf_8' in tested):
            probable_result = early_stop_results.best()
            logger.debug('Encoding detection: %s is most likely the one.', probable_result.encoding)
            if explain:
                logger.removeHandler(explain_handler)
                logger.setLevel(previous_logger_level)
            return CharsetMatches([probable_result])
        if (not definitive_match_found and not is_multi_byte_decoder):
            best_coherence = (max((v for (_, v) in cd_ratios_merged), default=0.0) if cd_ratios_merged else 0.0)
            if (best_coherence >= 0.5 and 'ascii' in tested and 'utf_8' in tested):
                definitive_match_found = True
                definitive_target_languages.update(target_languages)
                logger.log(TRACE, 'Definitive match found: %s (chaos=%.3f, coherence=%.2f). Encodings targeting different language families will be skipped.', encoding_iana, mean_mess_ratio, best_coherence)
        if (not mb_definitive_match_found and is_multi_byte_decoder and multi_byte_bonus and decoded_payload is not None and len(decoded_payload) < length * 0.98 and encoding_iana not in {'utf_8', 'utf_8_sig', 'utf_16', 'utf_16_be', 'utf_16_le', 'utf_32', 'utf_32_be', 'utf_32_le', 'utf_7'} and 'ascii' in tested and 'utf_8' in tested):
            mb_definitive_match_found = True
            logger.log(TRACE, 'Multi-byte definitive match: %s (chaos=%.3f, decoded=%d/%d=%.1f%%). Single-byte encodings will be skipped.', encoding_iana, mean_mess_ratio, len(decoded_payload), length, len(decoded_payload) / length * 100)
        if encoding_iana == sig_encoding:
            logger.debug('Encoding detection: %s is most likely the one as we detected a BOM or SIG within the beginning of the sequence.', encoding_iana)
            if explain:
                logger.removeHandler(explain_handler)
                logger.setLevel(previous_logger_level)
            return CharsetMatches([results[encoding_iana]])
    if len(results) == 0:
        if (fallback_u8 or fallback_ascii or fallback_specified):
            logger.log(TRACE, 'Nothing got out of the detection process. Using ASCII/UTF-8/Specified fallback.')
        if fallback_specified:
            logger.debug('Encoding detection: %s will be used as a fallback match', fallback_specified.encoding)
            results.append(fallback_specified)
        elif ((fallback_u8 and fallback_ascii is None) or (fallback_u8 and fallback_ascii and fallback_u8.fingerprint != fallback_ascii.fingerprint) or fallback_u8 is not None):
            logger.debug('Encoding detection: utf_8 will be used as a fallback match')
            results.append(fallback_u8)
        elif fallback_ascii:
            logger.debug('Encoding detection: ascii will be used as a fallback match')
            results.append(fallback_ascii)
    if results:
        logger.debug('Encoding detection: Found %s as plausible (best-candidate) for content. With %i alternatives.', results.best().encoding, len(results) - 1)
    else:
        logger.debug('Encoding detection: Unable to determine any suitable charset.')
    if explain:
        logger.removeHandler(explain_handler)
        logger.setLevel(previous_logger_level)
    return results

charset_normalizer.cd.unicode_range_lang:
def unicode_range_languages(primary_range: str) -> list[str]:
    """
    Return inferred languages used with a unicode range.
    """
    languages: list[str] = []
    for (language, characters) in FREQUENCIES.items():
        for character in characters:
            codepoint = ord(character)
            info = (_ASCII_CHAR_INFO[codepoint] if codepoint < 128 else _char_info(character))
            if info.range == primary_range:
                languages.append(language)
                break
    return languages

charset_normalizer.utils.cut_sequence_ch:
def cut_sequence_chunks(sequences: bytes | bytearray, encoding_iana: str, offsets: range, chunk_size: int, bom_or_sig_available: bool, strip_sig_or_bom: bool, sig_payload: bytes, is_multi_byte_decoder: bool, decoded_payload: str | None = None, deferred_decoding: bool = False) -> Generator[(str, None, None)]:
    if (decoded_payload and not is_multi_byte_decoder):
        for i in offsets:
            chunk = decoded_payload[i:i + chunk_size]
            if not chunk:
                break
            yield chunk
    elif deferred_decoding:
        base_bytes = (sequences if not strip_sig_or_bom else sequences[len(sig_payload):])
        for i in offsets:
            cut_sequence = base_bytes[i:i + chunk_size]
            if not cut_sequence:
                break
            yield str(cut_sequence, encoding_iana)
    else:
        for i in offsets:
            chunk_end = i + chunk_size
            if chunk_end > len(sequences) + 8:
                continue
            cut_sequence = sequences[i:i + chunk_size]
            if (bom_or_sig_available and not strip_sig_or_bom):
                cut_sequence = sig_payload + cut_sequence
            chunk = cut_sequence.decode(encoding_iana, errors=('ignore' if is_multi_byte_decoder else 'strict'))
            if (is_multi_byte_decoder and i > 0):
                chunk_partial_size_chk: int = min(chunk_size, 16)
                if (decoded_payload and chunk[:chunk_partial_size_chk] not in decoded_payload):
                    for j in range(i, i - 4, -1):
                        cut_sequence = sequences[j:chunk_end]
                        if (bom_or_sig_available and not strip_sig_or_bom):
                            cut_sequence = sig_payload + cut_sequence
                        chunk = cut_sequence.decode(encoding_iana, errors='ignore')
                        if chunk[:chunk_partial_size_chk] in decoded_payload:
                            break
            yield chunk

charset_normalizer.cd.mb_encoding_langua:
@lru_cache()
def mb_encoding_languages(iana_name: str) -> list[str]:
    """
    Multi-byte encoding language association. Some code page are heavily linked to particular language(s).
    This function does the correspondence.
    """
    if (iana_name.startswith('shift_') or iana_name.startswith('iso2022_jp') or iana_name.startswith('euc_j') or iana_name == 'cp932'):
        return ['Japanese']
    if (iana_name.startswith('gb') or iana_name in ZH_NAMES):
        return ['Chinese']
    if (iana_name.startswith('iso2022_kr') or iana_name in KO_NAMES):
        return ['Korean']
    return []

charset_normalizer.cd.merge_coherence_ra:
def merge_coherence_ratios(results: list[CoherenceMatches]) -> CoherenceMatches:
    """
    This function merge results previously given by the function coherence_ratio.
    The return type is the same as coherence_ratio.
    """
    per_language_ratios: dict[(str, list[float])] = {}
    for result in results:
        for sub_result in result:
            (language, ratio) = sub_result
            if language not in per_language_ratios:
                per_language_ratios[language] = [ratio]
                continue
            per_language_ratios[language].append(ratio)
    merge = [(language, round(sum(per_language_ratios[language]) / len(per_language_ratios[language]), 4)) for language in per_language_ratios]
    return sorted(merge, key=lambda x: x[1], reverse=True)

charset_normalizer.cd.encoding_unicode_r:
def encoding_unicode_range(iana_name: str) -> list[str]:
    """
    Return associated unicode ranges in a single byte code page.
    """
    if is_multi_byte_encoding(iana_name):
        raise OSError('Function not supported on multi-byte code page')
    decoder = importlib.import_module(f'encodings.{iana_name}').IncrementalDecoder
    p: IncrementalDecoder = decoder(errors='ignore')
    seen_ranges: dict[(str, int)] = {}
    character_count: int = 0
    for i in range(64, 255):
        chunk: str = p.decode(bytes([i]))
        if chunk:
            chunk_codepoint = ord(chunk)
            character_range: str | None = (_ASCII_CHAR_INFO[chunk_codepoint].range if chunk_codepoint < 128 else _char_info(chunk).range)
            if character_range is None:
                continue
            if not is_unicode_range_secondary(character_range):
                if character_range not in seen_ranges:
                    seen_ranges[character_range] = 0
                seen_ranges[character_range] += 1
                character_count += 1
    return sorted([character_range for character_range in seen_ranges if seen_ranges[character_range] / character_count >= 0.15])

charset_normalizer.utils.identify_sig_or:
def identify_sig_or_bom(sequence: bytes | bytearray) -> tuple[(str | None, bytes)]:
    """
    Identify and extract SIG/BOM in given sequence.
    """
    for iana_encoding in ENCODING_MARKS:
        marks: bytes | list[bytes] = ENCODING_MARKS[iana_encoding]
        if isinstance(marks, bytes):
            marks = [marks]
        for mark in marks:
            if sequence.startswith(mark):
                return (iana_encoding, mark)
    return (None, b'')

charset_normalizer.utils.any_specified_e:
def any_specified_encoding(sequence: bytes | bytearray, search_zone: int = 8192) -> str | None:
    """
    Extract using ASCII-only decoder any specified encoding in the first n-bytes.
    """
    if not isinstance(sequence, (bytes, bytearray)):
        raise TypeError
    seq_len: int = len(sequence)
    decoded_zone: str = sequence[:min(seq_len, search_zone)].decode('ascii', errors='ignore')
    lowered_zone: str = decoded_zone.lower()
    if ('coding' not in lowered_zone and 'charset' not in lowered_zone):
        return None
    results: list[str] = findall(RE_POSSIBLE_ENCODING_INDICATION, decoded_zone)
    if len(results) == 0:
        return None
    for specified_encoding in results:
        specified_encoding = specified_encoding.lower().replace('-', '_')
        encoding_alias: str
        encoding_iana: str
        for (encoding_alias, encoding_iana) in aliases.items():
            if encoding_alias == specified_encoding:
                return encoding_iana
            if encoding_iana == specified_encoding:
                return encoding_iana
    return None

charset_normalizer.utils.is_multi_byte_e:
@lru_cache(maxsize=128)
def is_multi_byte_encoding(name: str) -> bool:
    """
    Verify is a specific encoding is a multi byte one based on it IANA name
    """
    if name in {'utf_8', 'utf_8_sig', 'utf_16', 'utf_16_be', 'utf_16_le', 'utf_32', 'utf_32_le', 'utf_32_be', 'utf_7'}:
        return True
    for provider in ('_codecs_cn', '_codecs_hk', '_codecs_iso2022', '_codecs_jp', '_codecs_kr', '_codecs_tw'):
        try:
            importlib.import_module(provider).getcodec(name)
        except (ImportError, AttributeError, LookupError):
            continue
        return True
    return False

idna.intranges.intranges_contain:
def intranges_contain(int_: int, ranges: tuple[(int, ...)]) -> bool:
    """Determine if `int_` falls into one of the ranges in `ranges`."""
    tuple_ = _encode_range(int_, 0)
    pos = bisect.bisect_left(ranges, tuple_)
    if pos > 0:
        (left, right) = _decode_range(ranges[pos - 1])
        if left <= int_ < right:
            return True
    if pos < len(ranges):
        (left, _) = _decode_range(ranges[pos])
        if left == int_:
            return True
    return False

idna.core.check_bidi:
def check_bidi(label: str, check_ltr: bool = False) -> bool:
    """Validate the Bidi Rule from :rfc:`5893` for a single label.

    The Bidi Rule constrains how bidirectional characters (Hebrew, Arabic,
    etc.) may appear within a label. By default the check is only applied
    when the label contains at least one right-to-left character (Unicode
    bidirectional categories ``R``, ``AL``, or ``AN``); set ``check_ltr``
    to ``True`` to apply it to LTR-only labels as well.

    :param label: The label to validate, as a Unicode string.
    :param check_ltr: If ``True``, apply the rules even when the label
        contains no RTL characters.
    :returns: ``True`` if the label satisfies the Bidi Rule.
    :raises IDNABidiError: If any of Bidi Rule conditions 1-6 are violated,
        or if the directional category of a codepoint cannot be determined.
    """
    if len(label) > _max_input_length:
        raise IDNAError('Label too long')
    bidi_label = False
    for (idx, cp) in enumerate(label, 1):
        direction = unicodedata.bidirectional(cp)
        if direction == '':
            raise IDNABidiError(f'Unknown directionality in label {label!r} at position {idx}')
        if direction in _bidi_rtl_categories:
            bidi_label = True
    if (not bidi_label and not check_ltr):
        return True
    direction = unicodedata.bidirectional(label[0])
    if direction in _bidi_rtl_first:
        rtl = True
    elif direction == 'L':
        rtl = False
    else:
        raise IDNABidiError(f'First codepoint in label {label!r} must be directionality L, R or AL')
    valid_ending = False
    number_type: Optional[str] = None
    for (idx, cp) in enumerate(label, 1):
        direction = unicodedata.bidirectional(cp)
        if rtl:
            if direction not in _bidi_rtl_allowed:
                raise IDNABidiError(f'Invalid direction for codepoint at position {idx} in a right-to-left label')
            if direction in _bidi_rtl_valid_ending:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False
            if direction in _bidi_rtl_numeric:
                if not number_type:
                    number_type = direction
                elif number_type != direction:
                    raise IDNABidiError('Can not mix numeral types in a right-to-left label')
        else:
            if direction not in _bidi_ltr_allowed:
                raise IDNABidiError(f'Invalid direction for codepoint at position {idx} in a left-to-right label')
            if direction in _bidi_ltr_valid_ending:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False
    if not valid_ending:
        raise IDNABidiError('Label ends with illegal codepoint directionality')
    return True

idna.core.check_label:
def check_label(label: Union[(str, bytes, bytearray)]) -> None:
    """Run the full set of IDNA 2008 validity checks on a single label.

    Applies, in order: NFC normalisation (:func:`check_nfc`), hyphen
    restrictions (:func:`check_hyphen_ok`), the no-leading-combiner rule
    (:func:`check_initial_combiner`), per-codepoint validity (PVALID,
    CONTEXTJ, CONTEXTO classes from :rfc:`5892`), and the Bidi Rule
    (:func:`check_bidi`).

    :param label: The label to validate. ``bytes`` or ``bytearray`` input
        is decoded as UTF-8 first.
    :raises IDNAError: If the label is empty or fails a structural rule.
    :raises InvalidCodepoint: If the label contains a DISALLOWED or
        UNASSIGNED codepoint.
    :raises InvalidCodepointContext: If a CONTEXTJ or CONTEXTO codepoint
        is not valid in its context.
    :raises IDNABidiError: If the Bidi Rule is violated.
    """
    if len(label) > _max_input_length:
        raise IDNAError('Label too long')
    if isinstance(label, (bytes, bytearray)):
        label = label.decode('utf-8')
    if len(label) == 0:
        raise IDNAError('Empty Label')
    if not valid_string_length(label, trailing_dot=True):
        raise IDNAError('Label too long')
    check_nfc(label)
    check_hyphen_ok(label)
    check_initial_combiner(label)
    for (pos, cp) in enumerate(label):
        cp_value = ord(cp)
        if intranges_contain(cp_value, idnadata.codepoint_classes['PVALID']):
            continue
        if intranges_contain(cp_value, idnadata.codepoint_classes['CONTEXTJ']):
            try:
                if not valid_contextj(label, pos):
                    raise InvalidCodepointContext(f'Joiner {_unot(cp_value)} not allowed at position {pos + 1} in {label!r}')
            except ValueError as err:
                raise IDNAError(f'Unknown codepoint adjacent to joiner {_unot(cp_value)} at position {pos + 1} in {label!r}') from err
        elif intranges_contain(cp_value, idnadata.codepoint_classes['CONTEXTO']):
            if not valid_contexto(label, pos):
                raise InvalidCodepointContext(f'Codepoint {_unot(cp_value)} not allowed at position {pos + 1} in {label!r}')
        else:
            raise InvalidCodepoint(f'Codepoint {_unot(cp_value)} at position {pos + 1} of {label!r} not allowed')
    check_bidi(label)

idna.core.valid_contexto:
def valid_contexto(label: str, pos: int, exception: bool = False) -> bool:
    """Validate the CONTEXTO rules from :rfc:`5892` Appendix A.

    Covers the contextual rules for codepoints such as MIDDLE DOT
    (``U+00B7``), Greek lower numeral sign, Hebrew punctuation, Katakana
    middle dot, and the Arabic-Indic / Extended Arabic-Indic digit ranges.

    :param label: The label containing the codepoint.
    :param pos: Index of the codepoint within ``label``.
    :param exception: Reserved for forward compatibility; currently unused.
    :returns: ``True`` if the codepoint at ``pos`` satisfies its CONTEXTO
        rule, ``False`` otherwise (including when the codepoint is not a
        recognised CONTEXTO codepoint).
    :raises IDNAError: If ``label`` exceeds the defensive input length limit.
    """
    if len(label) > _max_input_length:
        raise IDNAError('Label too long')
    cp_value = ord(label[pos])
    if cp_value == 183:
        return (0 < pos < len(label) - 1 and ord(label[pos - 1]) == 108 and ord(label[pos + 1]) == 108)
    if cp_value == 885:
        if (pos < len(label) - 1 and len(label) > 1):
            return _is_script(label[pos + 1], 'Greek')
        return False
    if cp_value in {1523, 1524}:
        if pos > 0:
            return _is_script(label[pos - 1], 'Hebrew')
        return False
    if cp_value == 12539:
        for cp in label:
            if cp == '・':
                continue
            if (_is_script(cp, 'Hiragana') or _is_script(cp, 'Katakana') or _is_script(cp, 'Han')):
                return True
        return False
    if 1632 <= cp_value <= 1641:
        return not any((1776 <= ord(cp) <= 1785 for cp in label))
    if 1776 <= cp_value <= 1785:
        return not any((1632 <= ord(cp) <= 1641 for cp in label))
    return False
